package ama.localdev;
import ama.config.*;import ama.config.file.*;import ama.contract.ConfigArchiveContracts.*;import ama.minutes.ControlledMinutesAdmin;import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;
/** Append-only local installation of the explicit document parser. No business DML or credential output. */
public final class LocalDocumentSetup {
 public static void main(String[] args)throws Exception{
  if(!"1".equals(System.getenv("AMA_LOCAL_DEV"))||args.length!=2)throw new IllegalArgumentException("Explicit local document installation required");System.out.println(new ObjectMapper().writeValueAsString(install(Path.of(args[0]).toRealPath(),args[1],List.of(new String[]{"document-parser-v1","PARSER_CONFIG","ama.office-documents.v1"},new String[]{"document-processing-v1","PROCESSING_CONFIG","ama.import-documents.v1"}),"ama.import-documents.v1")));
 }
 static Map<String,String> install(Path root,String previous,List<String[]> resources,String processingVersion)throws Exception{
  var source=new ControlledConfigArchiveSource();var old=source.open(root,previous,ControlledMinutesAdmin.INDEX,ControlledMinutesAdmin.READ,()->false);var added=new ArrayList<RawArchive>();for(var entry:resources){try(var in=LocalDocumentSetup.class.getResourceAsStream("/ama/transcript/"+entry[0]+".json")){byte[] bytes=Objects.requireNonNull(in).readNBytes(65537);if(bytes.length>65536)throw new IllegalArgumentException("Archive bound");added.add(new RawArchive(ArtifactType.valueOf(entry[1]),entry[2],bytes));}}
  // A deterministic next index permits recovery after publication-before-receipt without overwriting a release.
  var entries=new ArrayList<>(old.index().entries());for(var raw:added){String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.bytes()));entries.add(new ConfigArchiveIndex.Entry(new Ref(raw.claimedArtifactType(),raw.claimedVersion(),sha),raw.bytes().length));}entries.sort(Comparator.comparing((ConfigArchiveIndex.Entry e)->e.ref().artifactType().name()).thenComparing(e->e.ref().version()));var index=new ConfigArchiveIndex(old.index().generation()+1,previous,entries);byte[] wire=ama.config.CanonicalJson.encode(index.wire(),4194304,()->false);String expected=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(wire));String pin;
  if(Files.exists(root.resolve("releases").resolve(expected),LinkOption.NOFOLLOW_LINKS)){source.open(root,expected,ControlledMinutesAdmin.INDEX,ControlledMinutesAdmin.READ,()->false);pin=expected;}else pin=new ControlledArchiveReleaseWriter().publish(root,previous,added,ControlledMinutesAdmin.INDEX,ControlledMinutesAdmin.READ,()->false);
  if(!expected.equals(pin))throw new IllegalStateException("Document index identity mismatch");var snapshot=source.open(root,pin,ControlledMinutesAdmin.INDEX,ControlledMinutesAdmin.READ,()->false);var processing=snapshot.index().entries().stream().map(ConfigArchiveIndex.Entry::ref).filter(r->r.artifactType()==ArtifactType.PROCESSING_CONFIG&&r.version().equals(processingVersion)).findFirst().orElseThrow();snapshot.loadClosure(List.of(processing),ControlledMinutesAdmin.READ,0,()->false);return Map.of("processing.config-version",processing.version(),"processing.config-sha",processing.sha256(),"processing.index-sha",pin,"minutes.index-sha",pin);
 }
}
